// Read the actual JPEG dimensions rather than inferring orientation from print sizes.
function jpegDimensions(bytes){
  if(bytes[0]!==0xff||bytes[1]!==0xd8)throw Error('Not a JPEG');
  for(let at=2;at<bytes.length;){
    if(bytes[at++]!==0xff)continue;
    while(bytes[at]===0xff)at++;
    const marker=bytes[at++];
    if(marker===0xda||marker===0xd9)break;
    if(marker===0x01||(marker>=0xd0&&marker<=0xd7))continue;
    const length=bytes.readUInt16BE(at);
    if([0xc0,0xc1,0xc2,0xc3,0xc5,0xc6,0xc7,0xc9,0xca,0xcb,0xcd,0xce,0xcf].includes(marker))
      return [bytes.readUInt16BE(at+5),bytes.readUInt16BE(at+3)];
    at+=length;
  }
  throw Error('JPEG dimensions unavailable');
}
