  const heFinish=w.category==='accessible'?'אפשר לבחור קנבס מתוח ומוכן לתלייה, אלוקובונד מט או פרספקס מבריק.':'אפשר לבחור אלוקובונד מט או פרספקס מבריק עם מערכת תלייה נסתרת.';
  const featureLinkHe=w.featured?`<a class="featured-proof" href="${esc(w.featured.url)}" target="_blank" rel="noopener noreferrer"><span>פורסם ב־${esc(w.featured.publisher)}</span><strong>${esc(w.featured.reactions)} ${w.featured.primaryLabel==='likes'?'לייקים':'תגובות'} · ${esc(w.featured.secondary||w.featured.shares)} ${w.featured.secondaryLabel==='comments'?'תגובות':'שיתופים'}</strong><em>לצפייה בפרסום המקורי ↗</em></a>`:'';
  const livingRoomLink=[25,17,37,20,31].includes(w.id)?'<p class="product-help"><a href="/he/art-for-living-room/">למבחר תמונות לסלון ולצפייה בהדמיות בחלל</a></p>':'';
  const heHtml=`<!doctype html><html lang="he" dir="rtl"><head>${commonHead(`${w.title} — תמונה לסלון ואמנות ישראלית | CHIEF`,discoveryHeDescription,heUrl,image)}<link rel="alternate" hreflang="he" href="${heUrl}"><link rel="alternate" hreflang="en" href="${url}"><script type="application/ld+json">${JSON.stringify(heSchema)}</script><link rel="stylesheet" href="/product-room.css"><link rel="stylesheet" href="/product-stories.css"><script src="/product-stories.js" defer></script></head><body class="seo-body">${artworkHeaderHe}<main class="seo-main"><div class="seo-breadcrumbs"><a href="/he/">CHIEF בעברית</a> / <a href="/he/art-for-living-room/">תמונות לסלון</a> / ${esc(w.title)}</div><article class="product-seo product-he"><img src="${image}" alt="${esc(w.title)} — תמונה לסלון וצילום אמנותי ישראלי מאת CHIEF"><div class="product-details"><p>${labels[w.category]} · ${heEdition}</p><h1>${esc(w.title)}</h1><p>${heDescription}</p>${discoveryHeHtml}<p class="price">החל מ־${money(w.category==='accessible'?canvasPrices[0]:productPrices[0])}</p><table><tbody>${heRows}</tbody></table><p>${heFinish} כל עבודה מיוצרת לפי הזמנה ומגיעה עם תעודת מקוריות. ${productDeliveryHe}</p><a class="seo-cta" href="/?artwork=${w.id}&lang=he${w.category==='accessible'?'&finish=canvas':''}">לבחירת גודל וגימור · החל מ־${money(w.category==='accessible'?canvasPrices[0]:productPrices[0])}</a>${purchaseDetailsHe}${storySlot}<p class="collector-story-seo"><a href="/collector-stories/?lang=he&amp;artwork=${encodeURIComponent(w.title)}">כבר רכשתם את העבודה הזו? שתפו את סיפור ה־Collector שלכם לאחר שהיא תגיע לביתכם.</a></p>${featureLinkHe}${livingRoomLink}<p class="product-help"><a href="https://wa.me/972507123109">עזרה בהתאמת היצירה לסלון</a></p></div></article>${roomWidget('he')}</main></body></html>`;
