const guides={
  'art-for-home':{title:'תמונות לבית — צילום אמנותי במקום קישוט גנרי',description:'מדריך מעשי לבחירת תמונות לבית מתוך צילום אמנותי ישראלי מקורי, לפי חלל, גודל, צבע, חומר ותקציב.',intro:'תמונה לבית יכולה להשלים את העיצוב, אבל יצירת צילום טובה עושה יותר: היא מעניקה לחלל נקודת מבט, סיפור ונוכחות שחוזרים אליהם בכל יום. עבודות CHIEF נולדות מתוך מפגש ישיר עם הים, הרחוב, אור, השתקפות ורגעים בלתי צפויים — ולא מתוך מאגר תמונות גנרי.',sections:[['איך מתחילים לבחור?','מתחילים מהקיר ומהתחושה שרוצים ליצור. קיר מרכזי בסלון יכול לשאת עבודה גדולה ובעלת נוכחות, בעוד פינת אוכל, מבואה או חדר שינה עשויים להתאים ליצירה שקטה יותר או לצמד עבודות. לאחר מכן בוחנים מרחק צפייה, תאורה וצבעים קיימים בחלל.'],['תמונה שמתאימה לבית ולא רק לספה','אין צורך שהיצירה תחזור בדיוק על צבעי הרהיטים. לעיתים דווקא גוון מנוגד, כתם אור או קומפוזיציה מפתיעה הם שמעניקים לחדר עומק. הבחירה הטובה ביותר מחברת בין העיצוב לבין משהו אישי שהצופה מרגיש מול העבודה.'],['מה מקבלים עם יצירת CHIEF?','כל עבודה מיוצרת לפי הזמנה בגודל ובגימור שנבחרו. עבודות במהדורות מוגבלות חתומות וממוספרות ומגיעות עם תעודת מקוריות. ניתן לבחור בין אלוקובונד מט, פרספקס מבריק, וב־Art Edition גם קנבס מוכן לתלייה.']],tips:['בחרו קודם את הקיר ואת מרחק הצפייה.','העדיפו יצירה שאתם רוצים לחזור אליה, לא רק צבע שמתאים לריהוט.','בדקו אם התאורה הישירה בחלל מחייבת גימור מט.','לקיר רחב אפשר לבחור עבודה גדולה או צמד מתואם.'],featured:[1,17,31,35]},
  'art-for-living-room':{title:'תמונות לסלון — אמנות ישראלית מקורית לבית',description:'מבחר תמונות לסלון וצילום אמנותי ישראלי מקורי מאת CHIEF, עם מחירים, גדלים, גימורים והדמיות לבחירת יצירה לקיר.',intro:'תמונה לסלון היא מוקד שחיים איתו בכל יום. כאן תמצאו צילום אמנותי ישראלי מקורי של ים, אור, השתקפויות, תל אביב ורגעים סוריאליסטיים — עבודות שמיוצרות לפי הזמנה על קנבס, אלוקובונד או פרספקס, ובמהדורות מוגבלות גם חתומות וממוספרות.',sections:[['איך לבחור תמונה מעל הספה','מדדו את רוחב הספה ואת השטח הפנוי מעליה. ברוב הסלונים, עבודה ברוחב של כחצי עד שני שלישים מרוחב הספה יוצרת יחס מאוזן. עבודה בגודל 70 × 105 ס״מ מעניקה נוכחות ברורה; לקיר מרכזי ורחב אפשר לבחור 100 × 150 ס״מ.'],['תאורה וגימור','בסלון מואר מאוד או מול חלונות, אלוקובונד מט מצמצם השתקפויות ומעניק נוכחות שקטה. פרספקס מוסיף עומק וברק ומתאים כאשר רוצים תחושה דרמטית ועשירה. קנבס נותן אופי רך ונגיש יותר ומגיע מתוח ומוכן לתלייה.'],['אמנות ישראלית עם מקור ותעודה','העבודות נוצרו מתוך מפגש ישיר עם הים, הרחוב והאור המקומי. כל יצירה מיוצרת לפי הזמנה; עבודות במהדורה מוגבלת חתומות וממוספרות, וכל עבודה מגיעה עם תעודת מקוריות.']],tips:['מדדו את רוחב הקיר והספה לפני בחירת המידה.','בדקו את היצירה גם מאזור הישיבה וגם מהכניסה לחלל.','בחרו אלוקובונד מט אם יש אור ישיר משמעותי.','אפשר לשלוח צילום של הקיר ולקבל עזרה בהתאמת יצירה וגודל.'],featured:[25,17,37,20,31,35,15,3,1,38,12,39],faqs:[['איזה גודל תמונה מתאים מעל ספה?','ברוב המקרים מומלץ שרוחב היצירה יהיה כחצי עד שני שלישים מרוחב הספה. לקיר מרכזי אפשר לבחור 70 × 105 או 100 × 150 ס״מ.'],['האם התמונות מגיעות מוכנות לתלייה?','כן. היצירות מיוצרות לפי הזמנה ומגיעות עם פתרון תלייה מתאים והוראות ברורות.'],['מה ההבדל בין קנבס, אלוקובונד ופרספקס?','קנבס מעניק מרקם רך ונגיש, אלוקובונד יוצר מראה מט ונקי עם פחות השתקפויות, ופרספקס מעניק עומק וברק דרמטי.'],['האם זו אמנות ישראלית מקורית?','כן. כל הצילומים נוצרו על ידי CHIEF בתל אביב. עבודות במהדורה מוגבלת חתומות וממוספרות, וכל עבודה מגיעה עם תעודת מקוריות.']]},
  'large-wall-art':{title:'תמונות גדולות לקיר — מדריך לגודל ולנוכחות',description:'איך לבחור תמונה גדולה לסלון ולקיר מרכזי, כולל מידות, פרופורציות, גובה תלייה וגימורי Fine Art.',intro:'תמונה גדולה אינה רק גרסה מוגדלת של תמונה קטנה. בקנה מידה נכון היא פועלת כמעט כמו חלון נוסף: היא משנה את תחושת העומק, מושכת את העין ומגדירה את האופי של כל החלל.',sections:[['איפה עבודה גדולה עובדת נכון?','קיר מעל ספה, פינת אוכל, מבואה רחבה, חדר ישיבות או חלל עבודה הם מקומות טבעיים לעבודה גדולה. חשוב לראות את הקיר בשלמותו ולבדוק שאין מתגים, מיזוג או רהיט גבוה שמפריעים לקומפוזיציה.'],['מידות ופרופורציות','עבודות CHIEF נבחרות זמינות עד 100 × 150 ס״מ. בחלל צר עדיף לפעמים פורמט אנכי; מעל ספה רחבה פורמט אופקי יוצר קשר טבעי עם הרהיט. בחלל עם תקרה גבוהה אפשר לתת לעבודה יותר גובה ומרווח.'],['תלייה ונקודת מבט','מרכז היצירה צריך להרגיש טבעי בגובה העיניים, אך בסלון מתחשבים גם בגובה הישיבה ובריהוט שמתחת. לפני ההזמנה מומלץ לסמן את המידות על הקיר באמצעות נייר או סרט סימון ולהתרחק לנקודת הצפייה הרגילה.']],tips:['סמנו את המידה על הקיר לפני ההזמנה.','השאירו מרווח נשימה מסביב לעבודה.','התאימו את כיוון היצירה לפרופורציות הקיר.','בקשו הדמיה בחלל כאשר מתלבטים בין שתי מידות.'],featured:[15,16,30,3]},
  'fine-art-photography':{title:'צילום אמנותי לבית — מה הופך צילום ל־Fine Art',description:'מה ההבדל בין פוסטר לצילום Fine Art, ומה המשמעות של מהדורה מוגבלת, חתימה, תעודת מקוריות וחומר ההדפסה.',intro:'צילום Fine Art נוצר מתוך חזון אמנותי ונועד להתקיים כיצירה עצמאית בחלל. הוא אינו רק תיעוד של מקום יפה. הבחירה ברגע, באור, בפרספקטיבה ובקשר בין המציאות לדמיון היא חלק מהיצירה עצמה.',sections:[['מקוריות ומהדורה','במהדורה מוגבלת נקבע מראש מספר העותקים שיופקו בגודל ובסדרה. כל עותק חתום וממוספר ונרשם במעקב המהדורות. המשמעות היא שההפקה אינה בלתי מוגבלת ושזהות היצירה נשמרת לאורך זמן.'],['תעודת מקוריות','תעודת המקוריות מחברת בין היצירה הפיזית, שם העבודה, מספר המהדורה, המידות, החומר והאמן. היא אינה קישוט נלווה אלא מסמך שמסייע לשמור על עקיבות ואמון.'],['הדפסה כחלק מהיצירה','הבחירה בין אלוקובונד, פרספקס וקנבס משנה את האופן שבו אור, שחור, צבע ומרקם פועלים בחלל. לכן חומר ההדפסה והגודל נבחרים כחלק מהחוויה האמנותית ולא רק כפתרון טכני.']],tips:['Super Premium מופק במהדורה של 7.','Premium ו־Open After Midnight מופקים במהדורה של 25.','כל עבודה במהדורה מוגבלת חתומה וממוספרת.','Art Edition מאפשרת כניסה נגישה יותר לצילום אמנותי מקורי.'],featured:[11,39,38,48]},
  'how-to-choose-wall-art-size':{title:'איך לבחור גודל תמונה לקיר — מדריך מדידה פשוט',description:'מדריך פשוט לבחירת גודל תמונה לקיר, מעל ספה, בפינת אוכל, בחדר שינה ובמסדרון.',intro:'הטעות הנפוצה בבחירת תמונה לקיר היא לבחור לפי גודל הקובץ על המסך. בחלל אמיתי צריך להתחשב ברוחב הקיר, ברהיט שמתחת, במרחק הצפייה ובכמות השטח הריק שמסביב.',sections:[['מעל ספה או מזנון','מדדו את רוחב הרהיט ואת השטח הפנוי מעליו. עבודה שרוחבה בערך חצי עד שני שלישים מרוחב הרהיט תרגיש בדרך כלל מחוברת לחלל. אם בוחרים צמד, מחשבים את רוחב שתי העבודות יחד עם הרווח ביניהן.'],['בקיר ללא רהיט','בקיר עצמאי אפשר לתת ליצירה יותר מרחב ולהתייחס לגובה התקרה ולמסלול התנועה בחדר. עבודה אנכית מדגישה גובה; עבודה אופקית מרחיבה את תחושת הקיר.'],['בדיקה לפני הזמנה','סמנו על הקיר מלבן בגודל המיועד באמצעות סרט נייר שאינו פוגע בצבע. הסתכלו עליו בבוקר ובערב, מהכניסה לחדר וממקום הישיבה. הבדיקה הפשוטה הזו מונעת בחירה קטנה מדי.']],tips:['50 × 75 ס״מ מתאים לפינה ממוקדת או לקיר בינוני.','70 × 105 ס״מ יוצר נוכחות ברורה ברוב הסלונים.','100 × 150 ס״מ מתאים לקיר מרכזי ולחלל רחב.','בצמד עבודות יש לחשב גם את הרווח ביניהן.'],featured:[1,15,20,31]},
  'alucobond-vs-perspex-vs-canvas':{title:'אלוקובונד, פרספקס או קנבס — איך לבחור חומר להדפסה',description:'השוואה מעשית בין אלוקובונד מט, פרספקס מבריק וקנבס לצילום אמנותי בבית.',intro:'אותו צילום נראה ומרגיש אחרת על כל חומר. הבחירה הנכונה תלויה באופי העבודה, בתאורה בחדר, במרחק הצפייה ובתחושה שרוצים ליצור.',sections:[['אלוקובונד — נקי ומאופק','אלוקובונד מעניק משטח יציב, חד ומודרני עם פחות השתקפויות. הוא מתאים לחללים בהירים, לקירות מול חלונות ולמי שמעדיף שהצילום עצמו יהיה במרכז ללא ברק דומיננטי.'],['פרספקס — עומק וברק','פרספקס מעניק לצבעים ולשחורים עומק חזותי וברק יוקרתי. הוא מתאים במיוחד לעבודות דרמטיות ולחללים שבהם ניתן לשלוט בתאורה. יש לקחת בחשבון השתקפויות ממקורות אור ישירים.'],['קנבס — מרקם ונגישות','קנבס מוסיף מרקם ואופי רך יותר ומגיע מתוח ומוכן לתלייה. באתר CHIEF הוא זמין בעבודות Art Edition ומאפשר להכניס צילום אמנותי לחלל בתקציב נגיש יותר.']],tips:['בחרו אלוקובונד לחלל מואר או למראה שקט.','בחרו פרספקס לעומק, ברק ונוכחות דרמטית.','בחרו קנבס למרקם רך ולתקציב נגיש יותר.','התייחסו למיקום החלונות והמנורות לפני הבחירה.'],featured:[25,35,31,12]},
  'israeli-art-for-home':{title:'אמנות ישראלית לבית — צילום מקורי מתל אביב',description:'אמנות ישראלית לבית דרך צילום Fine Art מקורי של הים, הרחוב, האור והמרחב המקומי בתל אביב.',intro:'אמנות ישראלית לבית אינה חייבת להציג סמל מוכר או נוף גלויה. היא יכולה לשאת את האור המקומי, את קו החוף, את הצפיפות העירונית ואת המפגש המיוחד בין יומיום לסוריאליזם.',sections:[['הים כחומר אמנותי','בעבודות CHIEF הים אינו רק רקע. הוא מראה, במה וכוח שמפרק ומרכיב מחדש את מה שנמצא מולו. גלים, השתקפויות וחפצים יומיומיים הופכים לרגעים שקשה למקם בין מציאות לדמיון.'],['תל אביב דרך השתקפות','הרחוב התל־אביבי מופיע דרך שלוליות, חלונות, תנועה ואנשים חולפים. במקום לתאר את העיר באופן ישיר, הצילום מחפש את העיר שמתחת לעיר ואת הרגע שבו המוכר נעשה זר.'],['יצירה מקומית עם שפה אישית','רכישת צילום מקורי מחברת את הבית לעבודה של אמן חי ולסיפור יצירה מתמשך. היצירה מגיעה עם פרטי האמן, המהדורה והמקוריות, ולא כמוצר אנונימי שיוצר בכמות בלתי מוגבלת.']],tips:['חפשו שפה אמנותית שמדברת אליכם, לא רק נושא מקומי.','בדקו את פרטי המהדורה והמקוריות.','בחרו עבודה שמתאימה לאור ולאופי של הבית.','הכירו את הסיפור ואת תהליך העבודה של האמן.'],featured:[20,3,17,38]},
  'wall-art-colors-and-light':{title:'איך להתאים תמונה לצבע ולאור בבית',description:'מדריך להתאמת תמונה לסלון ולבית לפי צבעי הקיר, התאורה הטבעית, הגימור והאווירה הרצויה.',intro:'צבע ואור משנים את הדרך שבה יצירה נראית במהלך היום. צילום כחול ושקט יכול להיראות קריר בבוקר ועמוק בערב; עבודה שחור־לבן עשויה להבליט מרקמים כאשר התאורה מגיעה מהצד.',sections:[['התאמה לעומת ניגוד','אפשר לבחור יצירה שממשיכה את פלטת הצבעים של החדר, ואפשר להשתמש בה כניגוד שמכניס אנרגיה. בחלל ניטרלי עבודה צבעונית יכולה להיות מוקד; בחלל עשיר בצבע צילום מונוכרומטי מעניק איזון.'],['אור טבעי ואור מלאכותי','בדקו לאן נכנס אור ישיר במהלך היום ומה קורה בערב. תאורה חמה מעצימה זהב ואדום; תאורה קרה מדגישה כחול ואפור. מומלץ להימנע מהצבת מקור אור חזק שמחזיר השתקפות ישירה למרכז היצירה.'],['צבע הקיר והמרווח','קיר כהה יכול להעניק מסגרת טבעית לעבודה בהירה, וקיר לבן נותן לצבעים ולשחור לעבוד ללא תחרות. המרווח מסביב ליצירה חשוב לא פחות מהצבע עצמו ומאפשר לעין להתמקד.']],tips:['צלמו את הקיר באור יום ובערב לפני הבחירה.','השתמשו ביצירה צבעונית כמוקד בחלל ניטרלי.','בחרו אלוקובונד מט כאשר יש אור ישיר משמעותי.','השאירו שטח פנוי מסביב ליצירה.'],featured:[31,15,25,4]}
};
guides['art-for-living-room'].title='תמונות לסלון — צילום אמנותי ישראלי מקורי';
guides['art-for-living-room'].seoTitle='תמונות אמנות לסלון | צילום Fine Art ישראלי מקורי | CHIEF';
guides['art-for-living-room'].heading='תמונות אמנות לסלון — צילום Fine Art ישראלי מקורי';
guides['art-for-living-room'].metaDescription='תמונות אמנות לסלון מאת CHIEF — צילום Fine Art ישראלי מקורי על קנבס, אלוקובונד או פרספקס. כולל מהדורות חתומות ותעודת מקוריות לכל יצירה.';
guides['art-for-living-room'].description='תמונות לסלון וצילום אמנותי ישראלי מקורי מאת CHIEF, עם מחירים, גדלים, גימורים והדמיות לבחירת תמונה לסלון ולקיר מרכזי.';
guides['art-for-living-room'].intro='בחירת תמונה לסלון מתחילה ביצירה שרוצים לחיות איתה, לא רק בצבע שמתאים לספה. בעמוד הזה תמצאו תמונות לסלון וצילום אמנותי לבית מאת CHIEF: ים, אור, השתקפויות, תל אביב ורגעים שבהם המציאות הופכת למעט סוריאליסטית. המבחר כולל תמונות קיר לסלון בפורמט אופקי, אנכי ומרובע, מעבודות שקטות ועד יצירות גדולות ובעלות נוכחות לקיר מרכזי או מעל הספה. כל עבודה מיוצרת לפי הזמנה על קנבס, אלוקובונד מט או פרספקס מבריק, בהתאם לסדרה ולגודל. עבודות במהדורה מוגבלת מגיעות חתומות וממוספרות, וכל יצירה מגיעה עם תעודת מקוריות. אפשר לראות מחירים וגדלים בכל כרטיס, להיעזר בהדמיות של אמנות לסלון בחלל אמיתי, ולשלוח צילום של הקיר כדי לבחור יחד את היצירה, המידה והגימור המתאימים.';
guides['art-for-living-room'].featured=[25,17,37,20,31,35,15,3,1,38,12,39,30,16,24,32,14,34];
guides['large-wall-art'].title='תמונה ענקית לסלון — צילום אמנותי לקיר מרכזי';
guides['large-wall-art'].description='תמונה ענקית לסלון ויצירות צילום גדולות לקיר מרכזי מאת CHIEF, עד 100 × 150 ס״מ, עם התאמת חומר והדמיה לחלל.';
guides['large-wall-art'].intro='תמונה ענקית לסלון אינה רק גרסה מוגדלת של תמונה קטנה. כשהיצירה והקיר מתאימים זה לזה, הצילום פועל כמעט כמו חלון נוסף: הוא משנה את תחושת העומק, מושך את העין ומגדיר את אופי החלל.';
guides['how-to-choose-wall-art-size'].title='גודל תמונה סטנדרטית לקיר — מדריך מידות לסלון';
guides['how-to-choose-wall-art-size'].description='מהו גודל תמונה סטנדרטית לקיר ואיזו מידה מתאימה מעל ספה, בפינת אוכל, בחדר שינה או במסדרון — מדריך מדידה פשוט.';
guides['how-to-choose-wall-art-size'].intro='אין גודל תמונה סטנדרטית אחד שמתאים לכל קיר. הבחירה הנכונה נקבעת לפי רוחב הקיר, הרהיט שמתחת, מרחק הצפייה והשטח הריק מסביב. המדריך מרכז מידות שימושיות וכלל מדידה פשוט לפני הזמנה.';
