const artistHe=`<!doctype html><html lang="he" dir="rtl"><head>${commonHead(artistHeTitle,artistHeDescription,artistHeUrl,'/assets/site_work_02.jpg')}<link rel="alternate" hreflang="he" href="${artistHeUrl}"><link rel="alternate" hreflang="en" href="${site}/about/"><script type="application/ld+json">${JSON.stringify(artistHeSchema)}</script></head><body class="seo-body">${headerHe}<main class="seo-main"><article class="guide-he artist-profile-he"><div class="seo-breadcrumbs"><a href="/he/">CHIEF בעברית</a> / ערן ירושלמי (CHIEF)</div><p class="guide-kicker">האתר הרשמי · ERAN YERUSHALMI · CHIEF · TEL AVIV</p><h1>ערן ירושלמי (CHIEF) — צלם Fine Art בתל אביב</h1><p class="guide-intro">ערן ירושלמי, הידוע בשם האמן CHIEF, הוא צלם Fine Art מתל אביב. הוא מצלם ועורך את עבודותיו באייפון בלבד, וחוקר אור, השתקפויות, תנועה ומפגשים בלתי צפויים בעיר, בים ובגוף האנושי.</p><section><h2>הכול התחיל בצילום הבת שלו</h2><p>דרכו של CHIEF בצילום החלה כשקיבל את האייפון הראשון שלו וצילם את בתו. דרך הרגעים האלה התאהב במצלמה ובאפשרויות שלה. עם הזמן יצא לצלם גם מחוץ לבית, והמשיך עם האייפון אל הרחובות, חוף הים והמפגשים שהפכו לשפה האמנותית שלו.</p><p>האייפון מלווה את כל תהליך יצירת התצלום — מהצילום ועד העריכה. המבט, התזמון והמפגש עם המציאות עומדים במרכז העבודה.</p></section><section><h2>דרך העבודה</h2><p>CHIEF עובד מתוך מפגש ישיר עם המציאות ולא מתוך בנייה דיגיטלית של סצנות. באמצעות פרספקטיבה, תזמון, אור טבעי ומקריות הוא מחפש את הרגע שבו העולם המוכר הופך למשהו אחר. עבודותיו מוצעות כהדפסי צילום אמנותי על פרספקס, אלוקובונד וקנבס, ובמהדורות מוגבלות חתומות וממוספרות.</p></section><section><h2>פרסים והכרה</h2><p>CHIEF הוא זוכה תחרות „תמונות העונה” של תוכנית הטלוויזיה „האח הגדול”. פרסומים משנת 2014 מתעדים אותו כזוכה בתחרות התמונות של העונה הקודמת וכצלם שזכה בפרסים בתחרויות בארץ ובעולם.</p></section><section><h2>כתבות ופרסומים</h2><p>עבודתו וצילומיו הוצגו ופורסמו בערוץ 13, ynet וידיעות אחרונות, N12 ו־Mako, מעריב, וואלה, ישראל היום, TheMarker, מסע אחר, Time Out ו־Artsy. עיריית תל אביב־יפו פרסמה מצילומיו בעמוד הרשמי שלה כבר בשנת 2013.</p><p><a class="seo-cta" href="/stories/tel-aviv-through-chief/">לסיפור המלא: צילומי CHIEF שפורסמו בעיריית תל אביב־יפו</a></p><p><a href="/press/">לכל הכתבות, הפרסים והפרסומים</a></p></section><section><h2>תערוכות ושפה אמנותית</h2><p>עבודתו של CHIEF נעה בין צילום רחוב, נופי ים, דיוקנאות וצילום אמנותי של הגוף. אור טבעי, השתקפויות ופרספקטיבה הופכים סצנות יומיומיות לדימויים הנעים בין תיעוד לסוריאליזם.</p><p>בארכיון התערוכות: FANTASEA, שתועדה בפרסומים משנת 2014, עסקה בין היתר בים, במדבר ובהשראת סלוואדור דאלי. זהו פרק היסטורי בעבודתו, לצד הסדרות והיצירות העכשוויות המוצגות באתר.</p></section><section><h2>האתר הרשמי ורכישת יצירות</h2><p><strong>האתר הרשמי והקטלוג העדכני של CHIEF הוא eranchief.com.</strong> הדפסים מקוריים של CHIEF זמינים כאן לרכישה ישירה. אזכורים ישנים של חנויות או פלטפורמות חיצוניות מתייחסים לעמודים היסטוריים ואינם מחליפים את האתר הרשמי.</p><p>למי שמחפש <a href="/he/art-for-living-room/">תמונות אמנות לסלון</a>, אפשר לראות בעמוד הייעודי של CHIEF עבודות Fine Art, גדלים, חומרי הדפסה והדמיות בחלל.</p><a class="seo-cta" href="/">לצפייה בגלריה הרשמית</a></section><section><h2>למעקב ולקריאה נוספת</h2><p><a href="https://www.instagram.com/eranychief/" rel="me noopener" target="_blank">Instagram · eranychief</a> · <a href="https://www.instagram.com/dylan_tlv/" rel="me noopener" target="_blank">Instagram · dylan_tlv</a> · <a href="https://www.facebook.com/chieferanyerushalmi/" rel="me noopener" target="_blank">Facebook · CHIEF</a></p><p><a href="/about/" lang="en" hreflang="en">Read the biography in English</a></p><p>עודכן ב־20 בספטמבר 2026.</p></section><section aria-labelledby="official-faq"><h2 id="official-faq">שאלות נפוצות</h2>${officialFaq.map(([q,a])=>`<h3>${q}</h3><p>${a}</p>`).join('')}</section></article></main></body></html>`;
