await writeFile('dist/server/index.js', `import { handleCollectorStories } from './collector-stories-worker.js';
export default { async fetch(request, env) {
  const storyResponse = await handleCollectorStories(request, env);
  if (storyResponse) return storyResponse;
  const url = new URL(request.url);
  if (url.pathname === '/api/coupon' && request.method === 'POST') {
    let body;
    try { body = await request.json(); } catch { return Response.json({ error: 'Invalid request.' }, { status: 400 }); }
    const code = String(body.code || '').trim().toUpperCase();
    const coupons = { CHIEF10: 10, CHIEF20: 20, CHIEF30: 30 };
    const percent = coupons[code];
    if (!percent) return Response.json({ error: 'This code is not valid.' }, { status: 404, headers: { 'cache-control': 'no-store' } });
    return Response.json({ code, percent }, { headers: { 'cache-control': 'no-store' } });
  }
  if (url.pathname === '/api/fx' && request.method === 'GET') {
    try {
      const response = await fetch('https://www.boi.org.il/PublicApi/GetExchangeRates', { cf: { cacheTtl: 3600, cacheEverything: true } });
      if (!response.ok) throw new Error('Rate source unavailable');
      const data = await response.json();
      const rates = Object.fromEntries((data.exchangeRates || []).filter(x => ['USD', 'EUR'].includes(x.key)).map(x => [x.key, { ilsPerUnit: Number(x.currentExchangeRate), updated: x.lastUpdate }]));
      if (!rates.USD?.ilsPerUnit || !rates.EUR?.ilsPerUnit || !Number.isFinite(rates.USD.ilsPerUnit) || !Number.isFinite(rates.EUR.ilsPerUnit)) throw new Error('Invalid rates');
      return Response.json({ rates, source: 'Bank of Israel', chargeCurrency: 'ILS' }, { headers: { 'cache-control': 'public, max-age=3600' } });
    } catch {
      return Response.json({ error: 'Exchange rates temporarily unavailable.' }, { status: 503, headers: { 'cache-control': 'no-store' } });
    }
  }
  if (url.pathname === '/api/newsletter' && request.method === 'POST') {
    if (!env.DB) return Response.json({ error: 'Newsletter service is unavailable.' }, { status: 503 });
    let body;
    try { body = await request.json(); } catch { return Response.json({ error: 'Invalid request.' }, { status: 400 }); }
    if (body.website) return Response.json({ ok: true });
    const email = String(body.email || '').trim().toLowerCase();
    if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email) || email.length > 254) return Response.json({ error: 'Please enter a valid email address.' }, { status: 400 });
    const existing = await env.DB.prepare('SELECT id FROM newsletter_subscribers WHERE email = ?').bind(email).first();
    if (existing) return Response.json({ ok: true, alreadySubscribed: true });
    await env.DB.prepare('INSERT INTO newsletter_subscribers (email, source, created_at) VALUES (?, ?, ?)').bind(email, 'website', new Date().toISOString()).run();
    return Response.json({ ok: true }, { status: 201 });
  }
  const redirects = {
    '/works': '/collections/premium/',
    '/works/': '/collections/premium/',
    '/contact': '/#about',
    '/contact/': '/#about',
    '/press': '/press/',
    '/artworks/premium-05-59/': '/artworks/walking-the-edge-of-reflection-59/',
    '/he/artworks/premium-05-59/': '/he/artworks/walking-the-edge-of-reflection-59/',
    '/artworks/premium-26-78/': '/artworks/it-dreamed-the-city-awake-78/',
    '/he/artworks/premium-26-78/': '/he/artworks/it-dreamed-the-city-awake-78/',
    '/artworks/tel-aviv-rolled-twice-100/': '/artworks/three-versions-of-the-same-city-100/',
    '/he/artworks/tel-aviv-rolled-twice-100/': '/he/artworks/three-versions-of-the-same-city-100/',
    '/artworks/the-getaway-car-137/': '/artworks/wrong-turn-perfect-beach-137/',
    '/he/artworks/the-getaway-car-137/': '/he/artworks/wrong-turn-perfect-beach-137/',
    '/artworks/dead-end-154/': '/artworks/between-then-and-now-154/',
    '/he/artworks/dead-end-154/': '/he/artworks/between-then-and-now-154/',
    '/artworks/rain-check-161/': '/artworks/the-rain-left-one-color-behind-161/',
    '/he/artworks/rain-check-161/': '/he/artworks/the-rain-left-one-color-behind-161/'
  };
  if (redirects[url.pathname]) return Response.redirect(new URL(redirects[url.pathname], url.origin), 301);
  return env.ASSETS.fetch(request);
} };\n`);
